import json, urllib.request

API_KEY = "[REDACTED_GALAXY_API_KEY]"
BASE = "https://usegalaxy.org/api"
SEED_HISTORY_ID = "bbd44e69cb8906b5e93a44050a184393"

def req(url, method="GET", data=None):
    headers = {"x-api-key": API_KEY, "Accept": "application/json"}
    if data:
        data = json.dumps(data).encode()
        headers["Content-Type"] = "application/json"
    r = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        resp = urllib.request.urlopen(r)
        return json.loads(resp.read())
    except urllib.error.HTTPError as e:
        body = e.read().decode()
        print(f"Error {e.code}: {body}")
        return None

# Get seed history details
seed = req(f"{BASE}/histories/{SEED_HISTORY_ID}")
print("Seed history:", json.dumps({k: v for k, v in seed.items() if k in ('id', 'name', 'published', 'deleted')}, indent=2))

# Copy it by creating a new history from the seed
# We can use the histories API to clone
new_hist = req(f"{BASE}/histories", method="POST", data={
    "name": "Analysis: Most non-ref variants in oldest male",
    "history_id": SEED_HISTORY_ID,
    "all_datasets": True
})
if new_hist:
    print("\nNew history created:", json.dumps({k: v for k, v in new_hist.items() if k in ('id', 'name')}, indent=2))
else:
    # Try copying differently - create new history then copy contents
    print("Trying alternative approach...")
    new_hist = req(f"{BASE}/histories", method="POST", data={"name": "Analysis: Most non-ref variants in oldest male"})
    if new_hist:
        print("Created empty history:", new_hist.get('id'))
        # Copy contents from seed
        result = req(f"{BASE}/histories/{SEED_HISTORY_ID}/contents", method="POST", data={
            "target_history_id": new_hist['id'],
            "source": "hdca"  # copy all datasets
        })
        print("Copy result:", result)
PYEOF

